inputs.script:
const { recordId, action } = input.config();

const webhookUrls = {
    "Prepare Enrichment Prompt":
        "https://n8n.dulcy.io/webhook/REDACTED_PATH",

    "Run Enrichment":
        "https://n8n.dulcy.io/webhook/REDACTED_PATH",
};

if (!recordId) {
    throw new Error("Airtable did not provide a recordId.");
}

if (!action) {
    throw new Error("Enrichment Action is empty.");
}

const webhookUrl = webhookUrls[action];

if (!webhookUrl) {
    throw new Error(`Unsupported Enrichment Action: ${action}`);
}

const response = await fetch(webhookUrl, {
    method: "POST",
    headers: {
        "Content-Type": "application/json",
    },
    body: JSON.stringify({
        recordId,
        action,
    }),
});

const responseText = await response.text();

if (!response.ok) {
    throw new Error(
        `n8n returned ${response.status}: ${responseText}`
    );
}

output.set("success", true);
output.set("actionSent", action);
output.set("n8nResponse", responseText);
